// The backfill probes (recommendation-sorting follow-up): the stock
// reconciliation driven over the real store, the REAL detector predicate, and
// the real sweep — a pre-detector ≥90% row enters the ledger with its own
// progress stamp; below-floor, no-duration, and zero-position rows never
// backfill; an already-ledgered row is skipped with its stamp intact; the
// pass is idempotent, pokes the wake exactly when it landed rows, and the
// learned stock flows through the SAME sweep a live completion takes.

// TestRecsBackfillReconcilesStock: one backfill pass over a mixed stock —
// the 97% row ledgered with its own progress-write stamp, the prior ledger
// row untouched (no restamp, no double row) — and a rerun is a no-op that
// never pokes.
func TestRecsBackfillReconcilesStock(t *testing.T) {
	st, _, ctx, _ := recsProbeFixture(t)

	// The stock: pre-detector progress rows spanning every rule branch.
	putRecsProbeItem(t, ctx, st, "it_bf97", 1,
		`{"format": {"duration": "3600"}}`,
		`{"description": "d", "genres": ["Action"]}`)
	putRecsProbeItem(t, ctx, st, "it_bf50", 1,
		`{"format": {"duration": "3600"}}`,
		`{"description": "d", "genres": ["Comedy"]}`)
	putRecsProbeItem(t, ctx, st, "it_bfnodur", 1, `{}`,
		`{"description": "d", "genres": ["Drama"]}`)
	putRecsProbeItem(t, ctx, st, "it_bfzero", 1,
		`{"format": {"duration": "3600"}}`,
		`{"description": "d", "genres": ["SciFi"]}`)
	// A row ALREADY in the ledger (a detector-era completion) sitting beside a
	// fresh 97.2% progress write — the skip leg.
	prior := time.Now().Add(-time.Hour).UTC()
	putRecsProbeItem(t, ctx, st, "it_bfled", 1,
		`{"format": {"duration": "3600"}}`,
		`{"description": "d", "genres": ["Western"]}`)
	if err := st.InsertWatched(ctx, "it_bfled", 1, "", prior, access.System()); err != nil {
		t.Fatalf("InsertWatched it_bfled: %v", err)
	}
	for _, p := range []struct {
		id  string
		pos int64
	}{
		{"it_bf97", 3492},      // 97% — backfills
		{"it_bf50", 1800},      // 50% — never
		{"it_bfnodur", 999999}, // no duration — never
		{"it_bfzero", 0},       // zero position — not even listed
		{"it_bfled", 3500},     // 97.2% but already ledgered — skipped
	} {
		if _, err := st.PutProgress(ctx, p.id, p.pos, access.System()); err != nil {
			t.Fatalf("PutProgress %s: %v", p.id, err)
		}
	}
	drainRecsWake(t) // a clean wake slate

	newRecsBackfill(st)(ctx)

	// The queue holds exactly the two legitimately-completed rows, oldest
	// stamp first (the learning queue's completed_at order).
	itemIDs, _, _, completed, err := st.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	if len(itemIDs) != 2 || itemIDs[0] != "it_bfled" || itemIDs[1] != "it_bf97" {
		t.Fatalf("backfilled queue = %v, want [it_bfled it_bf97] (only completions, oldest first)", itemIDs)
	}
	if !completed[0].Equal(prior) {
		t.Fatalf("it_bfled completed_at = %v, want the ledger's original %v (no restamp)", completed[0], prior)
	}
	prog, err := st.GetProgress(ctx, "it_bf97", access.System())
	if err != nil {
		t.Fatalf("GetProgress it_bf97: %v", err)
	}
	wantStamp, err := time.Parse(time.RFC3339Nano, prog.UpdatedAt)
	if err != nil {
		t.Fatalf("parse progress stamp %q: %v", prog.UpdatedAt, err)
	}
	if !completed[1].Equal(wantStamp) {
		t.Fatalf("it_bf97 completed_at = %v, want the progress write's own stamp %v", completed[1], wantStamp)
	}
	if !drainRecsWake(t) {
		t.Fatal("recs wake not poked though the pass landed rows")
	}
	if drainRecsWake(t) {
		t.Fatal("wake held more than one pending poke")
	}

	// The rerun: every row is either ledgered or ruled out — a no-op pass,
	// queue unchanged, wake silent.
	newRecsBackfill(st)(ctx)
	itemIDs, _, _, _, err = st.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched rerun: %v", err)
	}
	if len(itemIDs) != 2 {
		t.Fatalf("queue after rerun = %v, want unchanged (the pass is idempotent)", itemIDs)
	}
	if drainRecsWake(t) {
		t.Fatal("no-op backfill poked the wake")
	}
}

// TestRecsBackfillNeverBackfillsNonCompletions: below-floor, no-duration, and
// zero-position stock rows never enter the ledger — the pass over an
// all-incomplete stock is a silent no-op (no rows, no poke).
func TestRecsBackfillNeverBackfillsNonCompletions(t *testing.T) {
	st, _, ctx, _ := recsProbeFixture(t)

	putRecsProbeItem(t, ctx, st, "it_bf50", 1,
		`{"format": {"duration": "3600"}}`,
		`{"description": "d", "genres": ["Comedy"]}`)
	putRecsProbeItem(t, ctx, st, "it_bfnodur", 1, `{}`,
		`{"description": "d", "genres": ["Drama"]}`)
	putRecsProbeItem(t, ctx, st, "it_bfzero", 1,
		`{"format": {"duration": "3600"}}`,
		`{"description": "d", "genres": ["SciFi"]}`)
	for _, p := range []struct {
		id  string
		pos int64
	}{
		{"it_bf50", 1800},
		{"it_bfnodur", 999999},
		{"it_bfzero", 0},
	} {
		if _, err := st.PutProgress(ctx, p.id, p.pos, access.System()); err != nil {
			t.Fatalf("PutProgress %s: %v", p.id, err)
		}
	}

	newRecsBackfill(st)(ctx)

	if got := watchedCount(t, ctx, st); got != 0 {
		t.Fatalf("watched rows = %d, want 0 (nothing in the stock completed)", got)
	}
	if drainRecsWake(t) {
		t.Fatal("wake poked without a backfilled row")
	}
}

// TestBackfillSlotAwareness (l6-accounts 5.3): the boot reconciliation is
// slot-aware — the dedupe key is the (user_id, item_id) PAIR, not the item.
// Pre-detector stock in the slot-0 legacy slot reconciles into slot 0
// (access.System, the documented boot-backfill scope); stock in user 5's slot
// reconciles into user 5's slot (the row's OWN user_id shapes the stamp — a
// stamp carries no visibility); a cross-slot duplicate (the item ledgered in
// slot 0 but ALSO mid-completion in user 5's slot) suppresses ONLY the slot-0
// leg and still lands user 5's row; an already-ledgered user row is skipped
// with its stamp intact. Asserted via direct SQL — the scoped reads cannot
// see other slots, and a foreign row in ANY slot is exactly the bug class.
func TestBackfillSlotAwareness(t *testing.T) {
	st, ctx := watchDetectFixture(t)

	dur := `{"format": {"duration": "3600"}}`
	putWatchItem(t, ctx, st, "it_sa_legacy", 1, dur, `{}`) // slot-0 stock only
	putWatchItem(t, ctx, st, "it_sa_user5", 1, dur, `{}`)  // user-5 stock only
	putWatchItem(t, ctx, st, "it_sa_both", 1, dur, `{}`)   // ledgered slot-0 + stock in BOTH slots
	putWatchItem(t, ctx, st, "it_sa_led5", 1, dur, `{}`)   // ledgered in user 5's slot already

	// The pre-detector stock: legacy rows via System, user rows via the
	// user's own viewer (PutProgress stamps the writing viewer's slot).
	for _, p := range []struct {
		itemID string
		pos    int64
		v      access.Viewer
	}{
		{"it_sa_legacy", 3500, access.System()},
		{"it_sa_user5", 3500, access.User(5, []int64{1}, nil)},
		{"it_sa_both", 3500, access.System()},
		{"it_sa_both", 3520, access.User(5, []int64{1}, nil)},
		{"it_sa_led5", 3510, access.User(5, []int64{1}, nil)},
	} {
		if _, err := st.PutProgress(ctx, p.itemID, p.pos, p.v); err != nil {
			t.Fatalf("PutProgress %s: %v", p.itemID, err)
		}
	}
	// The pre-existing ledger rows: a detector-era slot-0 completion and user
	// 5's own earlier completion — fixed stamps the pass must never restamp.
	prior := time.Now().Add(-2 * time.Hour).UTC().Truncate(time.Second)
	if err := st.InsertWatched(ctx, "it_sa_both", 1, "", prior, access.System()); err != nil {
		t.Fatalf("InsertWatched it_sa_both (slot 0): %v", err)
	}
	if err := st.InsertWatched(ctx, "it_sa_led5", 1, "", prior, access.User(5, nil, nil)); err != nil {
		t.Fatalf("InsertWatched it_sa_led5 (slot 5): %v", err)
	}
	drainRecsWake(t)

	newRecsBackfill(st)(ctx)

	got := watchedSlotRows(t, ctx, st)
	want := []string{
		"0:it_sa_both",   // pre-existing slot-0 row — kept, never restamped
		"0:it_sa_legacy", // reconciled INTO the legacy slot
		"5:it_sa_both",   // the cross-slot duplicate: user 5's OWN row lands
		"5:it_sa_led5",   // pre-existing user row — kept
		"5:it_sa_user5",  // reconciled INTO user 5's slot
	}
	if len(got) != len(want) {
		t.Fatalf("watched rows = %v, want exactly %v (per-(user,item) dedupe, no foreign slot)", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("watched rows = %v, want %v (slot %s missing or foreign row present)", got, want, want[i])
		}
	}
	if !watchedCompletedAt(t, ctx, st, 0, "it_sa_both").Equal(prior) {
		t.Fatalf("slot-0 it_sa_both restamped — want the original %v (already-ledgered rows are skipped, not reconciled)", prior)
	}
	if !watchedCompletedAt(t, ctx, st, 5, "it_sa_led5").Equal(prior) {
		t.Fatalf("slot-5 it_sa_led5 restamped — want the original %v", prior)
	}
	if !drainRecsWake(t) {
		t.Fatal("recs wake not poked though the pass landed rows")
	}

	// The rerun: every slot reconciled or ruled out — a no-op pass, the row
	// set unchanged.
	newRecsBackfill(st)(ctx)
	if got := watchedSlotRows(t, ctx, st); len(got) != len(want) {
		t.Fatalf("watched rows after rerun = %v, want unchanged (the pass is idempotent per slot)", got)
	}
	if drainRecsWake(t) {
		t.Fatal("no-op backfill poked the wake")
	}
}

// TestRecsBackfillEpisodeJoinsSeriesAndSweepLearns: an EPISODE's backfilled
// row carries the parsed series anchor, and the stock learns through the
// normal path — ONE sweep consumes the queue, the SERIES document's thriller
// weight lands through the join, and the queue stamps empty.
func TestRecsBackfillEpisodeJoinsSeriesAndSweepLearns(t *testing.T) {
	st, reg, ctx, _ := recsProbeFixture(t)

	if err := st.PutSeries(ctx, store.Series{
		ModuleID:     "serial",
		LibraryID:    1,
		RelativePath: "Backfill Show",
		Document: recsDoc(t, `{
			"serial-parser": {"season_episode": "S01E01"},
			"shikimori":     {"description": "d", "genres": ["Thriller"]}
		}`),
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
	putWatchItem(t, ctx, st, "it_bfep", 1,
		`{"format": {"duration": "3600"}}`,
		`{"series_relative_path": "Backfill Show"}`)
	if _, err := st.PutProgress(ctx, "it_bfep", 3500, access.System()); err != nil { // 97.2%
		t.Fatalf("PutProgress episode: %v", err)
	}
	drainRecsWake(t)

	newRecsBackfill(st)(ctx)

	itemIDs, _, seriesPaths, _, err := st.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	if len(itemIDs) != 1 || itemIDs[0] != "it_bfep" {
		t.Fatalf("backfilled queue = %v, want exactly [it_bfep]", itemIDs)
	}
	if seriesPaths[0] != "Backfill Show" {
		t.Fatalf("watched series path = %q, want %q (the join anchor must ride the backfilled row)", seriesPaths[0], "Backfill Show")
	}
	if !drainRecsWake(t) {
		t.Fatal("recs wake not poked though the episode backfilled")
	}

	// The learning pass over the backfilled stock — the same sweep a live
	// completion takes, the series join supplying the tags.
	newRecsSweep(st, reg)(ctx)
	recsAssertWeights(t, st, map[string]int64{"thriller": 1})
	recsAssertQueueEmpty(t, st)
}
